const raw = ($json.body?.message || '').trim();
const city = raw.replace(/^(cuaca di|cuaca|weather in|weather|info cuaca)\s*/i, '').trim() || 'Jakarta';
return { json: { city, geoUrl: `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=1&language=en&format=json` } };

const geo = $('Geocode Location').first().json.results?.[0] || { name: 'Lokasi', country: '' };
const cur = $json.current || {};
const daily = $json.daily || {};

let content = `🌤️ **[LAPORAN CUACA: ${geo.name}, ${geo.country}]**\n\n`;
content += `- **Suhu:** 🌡️ **${cur.temperature_2m}°C** *(Feels like: ${cur.apparent_temperature}°C)*\n`;
content += `- **Kelembapan:** 💧 **${cur.relative_humidity_2m}%**\n`;
content += `- **Kecepatan Angin:** 💨 **${cur.wind_speed_10m} km/h**\n`;
content += `- **Curah Hujan:** 🌧️ **${cur.precipitation} mm**\n\n`;

if (daily.time) {
  content += `### 📅 Prakiraan 3 Hari:\n`;
  for (let i = 0; i < Math.min(3, daily.time.length); i++) {
    content += `- **${daily.time[i]}:** ${daily.temperature_2m_min[i]}°C s/d ${daily.temperature_2m_max[i]}°C\n`;
  }
}

const chips = ['📍 Cuaca Tokyo', '📍 Cuaca London', '📍 Cuaca New York', '📍 Cuaca Mekkah'];
return { json: { content, chips } };
